#![no_std]
#![forbid(unsafe_code)]
extern crate alloc;

use alloc::{alloc::Global, rc::Rc, vec::Vec};
use core::alloc::Allocator;
use zstdoxide::{
    DecodeOptions, Decoder, Dictionary, DictionaryMode, DictionaryTrainingOptions, Encoder,
    EncoderOptions, EndDirective, RawTrainingOptions, Result, SharedDictionary, compress_in,
    compress_with_dictionary_in, decompress_in, decompress_with_dictionary_in,
    finalize_dictionary_in, train_dictionary_in, train_raw_dictionary_in,
};

#[cfg(target_has_atomic = "ptr")]
compile_error!("This compile-only probe requires the no-pointer-atomics Rc branch.");

// Exact type equality checks the generic alias, independently of any call site.
pub fn shared_is_rc<A: Allocator>(shared: SharedDictionary<A>) -> Rc<Dictionary<A>> {
    shared
}

// Every codec payload owner is generic in A or borrows A. No dictionary/context
// borrow escapes; the final frame retains the original allocator value.
pub fn selected_allocator<A: Allocator + Clone>(
    source: &[u8],
    frame: &[u8],
    allocator: A,
) -> Result<Vec<u8, A>> {
    {
        let dictionary = Dictionary::raw_in(b"common dictionary values", &allocator)?;
        let shared: Rc<Dictionary<&A>> = shared_is_rc(dictionary.into_shared());
        let alias: SharedDictionary<&A> = shared.clone();
        let mut encoder = Encoder::with_options_in(EncoderOptions::default(), &allocator)?;
        let mut scratch = [0_u8; 17];
        let _ = encoder.process(source, &mut scratch, EndDirective::Continue);
        encoder.reset_with_options(EncoderOptions::default())?;
        let _ = encoder.process(source, &mut scratch, EndDirective::Finish);

        let mut dictionary_encoder =
            Encoder::with_dictionary_in(EncoderOptions::default(), alias.clone(), &allocator)?;
        let _ = dictionary_encoder.process(source, &mut scratch, EndDirective::Continue);
        dictionary_encoder.reset();
        dictionary_encoder.set_prefix(alias.clone())?;
        let _ = dictionary_encoder.process(source, &mut scratch, EndDirective::Finish);

        let encoded = compress_with_dictionary_in(source, &alias, &allocator)?;
        let _decoded = decompress_with_dictionary_in(
            &encoded,
            &alias,
            DecodeOptions::new(source.len()),
            &allocator,
        )?;
        let mut decoder = Decoder::with_dictionary_in(
            DecodeOptions::new(source.len()),
            shared.clone(),
            &allocator,
        );
        let _ = decoder.process(frame, &mut scratch);
        decoder.reset();
        decoder.set_prefix(shared)?;
        let _ = decoder.process(frame, &mut scratch);
        decoder.reset_with_options(DecodeOptions::new(32));
    }
    {
        let samples = [
            source,
            b"application field names and recurring values".as_slice(),
        ];
        let options = DictionaryTrainingOptions {
            selection: RawTrainingOptions {
                dictionary_size: 256,
                max_sample_bytes: 4096,
                segment_size: 64,
            },
            dictionary_id: Some(0x1234_5678),
        };
        let raw = train_raw_dictionary_in(&samples, options.selection, &allocator)?;
        let trained = train_dictionary_in(&samples, options, &allocator)?;
        let finalized = finalize_dictionary_in(raw.content(), &samples, options, &allocator)?;
        let prepared = Dictionary::from_bytes_with_mode_in(
            finalized.as_bytes(),
            DictionaryMode::Formatted,
            &allocator,
        )?;
        let _encoded = compress_with_dictionary_in(source, &trained.view(), &allocator)?;
        let mut encoder =
            Encoder::with_dictionary_in(EncoderOptions::default(), prepared.view(), &allocator)?;
        let mut scratch = [0_u8; 17];
        let _ = encoder.process(source, &mut scratch, EndDirective::Finish);
        encoder.reset();
        encoder.set_prefix(trained.view())?;
        let _ = encoder.process(source, &mut scratch, EndDirective::Finish);
    }
    // Keep the existing plain decoding path concretely instantiated as well.
    let _ = decompress_in(frame, 64, &allocator);
    compress_in(source, allocator)
}

// These entry points force code generation for the generic owner and borrowed
// allocator forms. They do not execute on thumbv6m or install a target allocator.
pub fn instantiate_owned(source: &[u8], frame: &[u8]) -> Result<Vec<u8>> {
    selected_allocator(source, frame, Global)
}

pub fn instantiate_borrowed<'a>(
    source: &[u8],
    frame: &[u8],
    allocator: &'a Global,
) -> Result<Vec<u8, &'a Global>> {
    selected_allocator(source, frame, allocator)
}
